def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    # separator columns: all zeros
    nz = [x for x in range(W) if (g[:, x] != 0).any()]
    # group consecutive non-zero columns into pieces
    pieces = []
    for x in nz:
        if pieces and pieces[-1][-1] == x - 1:
            pieces[-1].append(x)
        else:
            pieces.append([x])
    out = np.zeros((8, 7), dtype=int)
    x = 3
    out[0, x] = 3
    emit(out, "Allocate the 8x7 canvas and place the start marker 3 at the top centre (x=3).")
    y = 1
    for p in pieces:
        if len(p) == 1:
            for _ in range(2):
                if y < 8:
                    out[y, x] = 2
                y += 1
            emit(out, f"Vertical bar piece at column {p[0]}: go straight down two rows at x={x}.")
        else:
            top_left = g[0, p[0]] != 0
            if top_left:  # step right
                cells = (x, x + 1); x += 1; d = "right"
            else:  # step left
                cells = (x - 1, x); x -= 1; d = "left"
            if y < 8:
                for c in cells:
                    if 0 <= c < 7:
                        out[y, c] = 2
            y += 1
            emit(out, f"L piece at columns {p[0]}-{p[-1]}: step {d}, drawing one row at columns {cells}.")
    emit(out, "Path complete.")
    return out
